window.Runtime=(()=>{
 const {e,icon,button}=UI;
 let ticks=0;
 const stateStyle={Starting:['clock','pending'],Preparing:['clock','pending'],Connecting:['refresh','pending'],Reconnecting:['refresh','pending'],Acquiring:['chart','active'],Recording:['save','active'],Live:['chart','active'],Connected:['link','good'],Acknowledged:['check','good'],Completed:['check','good'],Saved:['save','good'],Stopped:['stop','neutral'],Active:['power','active'],Requested:['clock','pending'],Frozen:['pause','neutral'],Paused:['pause','neutral'],Replay:['play','active'],Disconnected:['disconnect','bad'],'Partial failure':['alert','bad'],Interrupted:['alert','bad'],Uncertain:['alert','warn'],Unavailable:['disconnect','warn']};
 function status(value){const [ico,tone]=stateStyle[value]||['info','neutral'];return `<span class="runtime-state state-${tone}">${icon(ico)}<span>${e(value)}</span></span>`;}
 function ensure(run){if(!run.replay){const completed=run.acquisition==='Completed';run.replay={rangeMode:completed?'all':String(run.interval||60),startSeconds:0,endSeconds:run.seconds,cursorSeconds:completed?Math.min(run.cursor??0,run.seconds):run.seconds,playbackState:run.viewing==='Replay'?'playing':'paused',speed:1};}return run.replay;}
 function bounds(run){const r=ensure(run);if(run.acquisition!=='Completed'&&run.viewing==='Live'){r.endSeconds=run.seconds;r.startSeconds=r.rangeMode==='all'?0:Math.max(0,run.seconds-Number(r.rangeMode||60));r.cursorSeconds=run.seconds;}return r;}
 function position(run){return bounds(run).cursorSeconds;}
 function active(){return Cousins.getCollection(App.ui.route.split('/')[1]);}
 function log(run,text,extra={}){const severity=/interrupt|disconnect|unavailable|timeout|timed out|uncertain/i.test(text)?'warning':'info';const deviceId=Object.keys(run.deviceStates).find(id=>{const d=Cousins.getDevice(id);return d&&(text.includes(d.name)||text.startsWith(d.parameter+':'));})||null;const record=Capture.add({deviceId,collectionId:run.id,elapsedSeconds:run.seconds,severity,source:'Capture simulator',eventType:'capture.transition',message:text,details:{acquisition:run.acquisition,recording:run.recording},provenance:'Simulated capture',...extra});run.events.unshift({time:Cousins.duration(run.seconds),elapsedSeconds:run.seconds,text,logId:record.id,severity:record.severity,provenance:record.provenance});Cousins.save();}
 function rangeText(r){return `${Cousins.duration(r.startSeconds)} to ${Cousins.duration(r.endSeconds)}`;}
 function render(run){if(!run)return UI.empty('Collection not found');const r=bounds(run),completed=run.acquisition==='Completed',view=run.preset.views.find(v=>v.id===run.view)||run.preset.views[0];return `<div class="runtime-page"><header class="page-header"><div>${UI.breadcrumbs('Capture')}<h1>${e(run.name)}</h1></div><div class="actions">${completed?button('Export','export-run',{icon:'download'}):`${button(run.viewing==='Frozen'?'Resume live':'Freeze display','freeze',{icon:run.viewing==='Frozen'?'play':'pause'})}${button('Stop acquisition','stop-run',{icon:'stop',danger:true})}`}</div></header>
 <section class="capture-status-strip" aria-label="Collection state"><div class="capture-clock"><span>${completed?'Recording duration':'Acquisition elapsed'}</span><strong data-elapsed>${Cousins.duration(run.seconds)}</strong></div><div class="capture-status-items"><div><span>Acquisition</span>${status(run.acquisition)}</div><div><span>Recording</span>${status(run.recording)}</div><div><span>View</span><span data-view-state>${status(completed?(r.playbackState==='playing'?'Replay':'Paused'):run.viewing)}</span></div></div><div class="capture-policy"><span>Device failure</span><strong>${run.policy==='stop'?'Stop all devices':'Continue remaining'}</strong></div></section>
 ${run.recording==='Interrupted'?`<div class="alert-strip">${icon('alert')}<span>Recording interrupted at ${Cousins.duration(run.seconds)}. The gap will remain in the recording.</span>${button('Resume recording','recover-recording')}</div>`:''}
 <section class="replay-controls" aria-label="${completed?'Recording replay':'Display time range'}"><div class="capture-toolbar"><div class="capture-view-controls"><div class="view-tabs">${run.preset.views.map(v=>`<button data-action="run-view" data-id="${v.id}" class="${v.id===view.id?'active':''}">${e(v.name)}</button>`).join('')}</div><div class="actions">${['devices','events','logs'].map(t=>`<button class="btn quiet ${Diagnostics.state.tab===t?'selected':''}" data-action="open-${t}" data-diagnostics-trigger="${t}" aria-expanded="${Diagnostics.state.tab===t}" aria-controls="runtime-panel-host">${icon(t==='devices'?'device':t==='events'?'clock':'file')}${t==='logs'?'Capture logs':t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div></div><div class="capture-interval"><div class="range-heading"><strong>${completed?'Replay interval':'Display interval'}</strong><span data-range-summary>${rangeText(r)} · ${Math.round(r.endSeconds-r.startSeconds)} s</span></div><div class="range-options" role="group" aria-label="Time range">${[['30','Last 30 s'],['60','Last 1 min'],['300','Last 5 min'],['all','All']].map(([id,label])=>`<button class="range-chip ${r.rangeMode===id?'selected':''}" aria-pressed="${r.rangeMode===id}" data-action="range-preset" data-id="${id}">${label}</button>`).join('')}<button class="range-chip ${r.rangeMode==='custom'?'selected':''}" aria-pressed="${r.rangeMode==='custom'}" data-action="range-custom" aria-expanded="false" aria-controls="custom-range-form">${icon('sliders')}Custom</button></div>
</div></div>
 <form id="custom-range-form" class="custom-range-form" hidden novalidate><label class="field">Start<input name="from" value="${Cousins.duration(r.startSeconds)}" aria-describedby="range-help range-error"></label><label class="field">End<input name="to" value="${Cousins.duration(r.endSeconds)}" aria-describedby="range-help range-error"></label><button type="submit" class="btn primary">Apply</button>${button('Cancel','range-cancel')}<p id="range-help">Elapsed time, HH:MM:SS or seconds. Available 0 to ${run.seconds} s.</p><p id="range-error" role="alert"></p></form>
 ${completed?`<div class="replay-transport">${button(r.playbackState==='playing'?'Pause':'Play interval','replay',{icon:r.playbackState==='playing'?'pause':'play',disabled:run.seconds<=0})}${button('Restart interval','replay-restart',{icon:'undo',iconOnly:true,disabled:run.seconds<=0})}<div class="playhead-readout"><strong data-replay-time>${Cousins.duration(r.cursorSeconds)}</strong><span>/ <span data-replay-end>${Cousins.duration(r.endSeconds)}</span></span></div><label class="replay-scrubber"><span class="sr-only">Replay position</span><input type="range" min="${r.startSeconds}" max="${r.endSeconds}" step="0.1" value="${r.cursorSeconds}" data-replay-position aria-label="Replay position" aria-valuetext="${Cousins.duration(r.cursorSeconds)}"></label><label class="speed-control">Speed${UI.select('replay-speed',String(r.speed),['0.5','1','2','4'].map(value=>({value,label:value+'×'})),'data-replay-speed')}</label></div>`:''}</section>
 <div class="runtime-workspace ${Diagnostics.state.tab?'has-diagnostics':''}"><div class="runtime-canvas">${Components.grid(view.components,{run})}</div><div id="runtime-panel-host">${Diagnostics.state.tab?Diagnostics.panel(run):''}</div></div></div>`;}
 function paint(run){if(active()?.id!==run.id||!App.ui.route.startsWith('active/'))return;const r=bounds(run),completed=run.acquisition==='Completed';document.querySelector('[data-elapsed]')?.replaceChildren(document.createTextNode(Cousins.duration(run.seconds)));document.querySelector('[data-range-summary]')?.replaceChildren(document.createTextNode(rangeText(r)+' · '+Math.round(r.endSeconds-r.startSeconds)+' s'));document.querySelector('[data-replay-time]')?.replaceChildren(document.createTextNode(Cousins.duration(r.cursorSeconds)));document.querySelector('[data-replay-end]')?.replaceChildren(document.createTextNode(Cousins.duration(r.endSeconds)));const slider=document.querySelector('[data-replay-position]');if(slider){slider.min=r.startSeconds;slider.max=r.endSeconds;slider.value=r.cursorSeconds;slider.setAttribute('aria-valuetext',Cousins.duration(r.cursorSeconds));}const play=document.querySelector('[data-action="replay"]');if(play)play.innerHTML=icon(r.playbackState==='playing'?'pause':'play')+(r.playbackState==='playing'?'Pause':'Play interval');const state=document.querySelector('[data-view-state]');if(state)state.innerHTML=status(completed?(r.playbackState==='playing'?'Replay':'Paused'):run.viewing);
 document.querySelectorAll('.runtime-canvas [data-chart]').forEach(el=>{const chart=echarts.getInstanceByDom(el),c=JSON.parse(el.dataset.chart);if(!chart)return;const series=Charts.data(c,r.endSeconds,{start:r.startSeconds,end:r.endSeconds});chart.setOption({xAxis:c.chartType==='spectrum'?{}:{min:r.startSeconds,max:Math.max(r.startSeconds+0.1,r.endSeconds)},series:series.map((s,i)=>({data:s.values,markLine:i===0&&c.chartType!=='spectrum'?{silent:true,symbol:'none',label:{show:false},lineStyle:{type:'solid',width:1,color:getComputedStyle(document.documentElement).getPropertyValue('--muted').trim()},data:[{xAxis:r.cursorSeconds}]}:{data:[]}}))});});
 document.querySelectorAll('.runtime-canvas [data-metric]').forEach(el=>{const c=JSON.parse(el.dataset.metric);let value=Cousins.signal(r.cursorSeconds,c.channels?.[0]==='mz44'?1:0);if(c.process==='linear')value=value*(c.gain===undefined?1:Number(c.gain))+(Number(c.offset)||0);el.textContent=value.toFixed(2);});
 }
 function setRange(run,mode,start,end){const r=ensure(run);Object.assign(r,{rangeMode:mode,startSeconds:start,endSeconds:end,cursorSeconds:run.acquisition==='Completed'?start:end,playbackState:'paused'});run.cursor=r.cursorSeconds;run.viewing=run.acquisition==='Completed'?'Completed':mode==='custom'?'Frozen':'Live';Cousins.save();App.render();}
 function parseTime(text){const value=text.trim();if(/^\d+(\.\d+)?$/.test(value))return Number(value);const m=value.match(/^(\d+):([0-5]\d):([0-5]\d(?:\.\d+)?)$/);return m?Number(m[1])*3600+Number(m[2])*60+Number(m[3]):NaN;}
 function validateRange(form,run){const from=parseTime(form.elements.from.value),to=parseTime(form.elements.to.value);const message=!Number.isFinite(from)||!Number.isFinite(to)?'Enter HH:MM:SS or elapsed seconds.':from>=to?'End must be after start.':from<0||to>run.seconds?`Use a range between 0 and ${run.seconds} seconds.`:'';form.querySelector('#range-error').textContent=message;form.elements.from.setAttribute('aria-invalid',String(!!message));form.elements.to.setAttribute('aria-invalid',String(!!message));return {from,to,message};}
 document.addEventListener('submit',event=>{if(event.target.id!=='custom-range-form')return;event.preventDefault();const run=active(),result=validateRange(event.target,run);if(result.message){Capture.add({severity:'warning',source:'Replay',collectionId:run.id,eventType:'replay.invalid-range',message:result.message});return;}setRange(run,'custom',result.from,result.to);});
 document.addEventListener('focusout',event=>{if(event.target.closest('#custom-range-form')&&event.target.matches('input'))validateRange(event.target.form,active());});
 function seek(value){const run=active(),r=ensure(run);r.cursorSeconds=Math.max(r.startSeconds,Math.min(r.endSeconds,Number(value)));r.playbackState='paused';run.cursor=r.cursorSeconds;run.viewing='Completed';paint(run);Cousins.save();}
 function speed(value){const run=active();ensure(run).speed=Number(value);Cousins.save();}
 function start(name,preset){const run=Cousins.newCollection(name,preset);run.events=[];run.storage='Recordings';log(run,'Acquisition requested.');App.navigate('active/'+run.id);setTimeout(()=>{if(run.acquisition!=='Starting')return;run.acquisition='Acquiring';run.recording='Recording';for(const s of Object.values(run.deviceStates)){s.connection='Connected';s.command='Acknowledged';s.operation='Acquiring';}log(run,'Acquisition started.');if(active()?.id===run.id)App.render();},1000);}
 function action(action,id,el){const run=active();if(!run)return false;const r=bounds(run);
 if(action==='run-view'){run.view=id;Cousins.save();App.render();return true;}
 if(action==='range-custom'){const f=document.getElementById('custom-range-form');f.hidden=false;el.setAttribute('aria-expanded','true');f.elements.from.focus();return true;}
 if(action==='range-cancel'){document.getElementById('custom-range-form').hidden=true;const b=document.querySelector('[data-action="range-custom"]');b.setAttribute('aria-expanded','false');b.focus();return true;}
 if(action==='range-preset'){const end=run.seconds;setRange(run,id,id==='all'?0:Math.max(0,end-Number(id)),end);return true;}
 if(action==='replay'||action==='replay-restart'){if(run.acquisition!=='Completed')return true;if(action==='replay-restart'){r.cursorSeconds=r.startSeconds;r.playbackState='paused';}else{if(r.cursorSeconds>=r.endSeconds)r.cursorSeconds=r.startSeconds;r.playbackState=r.playbackState==='playing'?'paused':'playing';}run.viewing=r.playbackState==='playing'?'Replay':'Completed';run.cursor=r.cursorSeconds;paint(run);Cousins.save();return true;}
 if(action==='freeze'){if(run.viewing==='Frozen'){if(r.rangeMode==='custom')r.rangeMode='60';run.viewing='Live';}else run.viewing='Frozen';log(run,run.viewing==='Frozen'?'Display frozen. Acquisition continues.':'Live display resumed.');App.render();return true;}
 if(action==='stop-run'){App.confirm('Stop acquisition?',`Stop devices and finish recording “${run.name}”.`,'Stop acquisition',()=>{run.acquisition='Completed';run.recording='Saved';run.viewing='Completed';run.replay={rangeMode:'all',startSeconds:0,endSeconds:run.seconds,cursorSeconds:run.seconds,playbackState:'paused',speed:1};for(const s of Object.values(run.deviceStates)){s.command='Completed';s.operation='Stopped';}log(run,'Recording completed.');App.render();});return true;}
 if(action==='export-run'){App.navigate('collection/'+run.id+'/export');return true;}
 if(run.acquisition==='Completed'&&['command','group-command','apply-parameter','reconnect','recover-recording','simulate-disconnect','simulate-storage','simulate-uncertain'].includes(action)){App.toast('This recording is complete. Start a new acquisition to operate devices.');return true;}
 if(action==='simulate-disconnect'){const s=Object.values(run.deviceStates)[0];s.connection='Disconnected';s.command='Uncertain';s.operation='Unavailable';run.acquisition=run.policy==='stop'?'Stopped':'Partial failure';if(run.policy==='stop')for(const other of Object.values(run.deviceStates))other.operation='Stopped';log(run,'Device disconnected. Failure policy applied.');}
 else if(action==='simulate-storage'){run.recording='Interrupted';log(run,'Storage unavailable. Recording interrupted.');}
 else if(action==='simulate-uncertain'){Object.values(run.deviceStates)[0].command='Uncertain';log(run,'Command acknowledgement timed out.');}
 else if(action==='reconnect'){for(const s of Object.values(run.deviceStates))if(s.connection==='Disconnected')s.connection='Reconnecting';log(run,'Reconnecting device.');setTimeout(()=>{for(const s of Object.values(run.deviceStates)){s.connection='Connected';s.command='Completed';s.operation='Acquiring';}run.acquisition='Acquiring';log(run,'Device reconnected.');if(active()?.id===run.id)App.render();},1000);}
 else if(action==='recover-recording'){run.recording='Recording';log(run,'Recording resumed in a new segment. Earlier gap retained.');}
 else if(action==='group-command'){const starting=el.dataset.command==='Start group';for(const [deviceId,status] of Object.entries(run.deviceStates)){const device=Cousins.getDevice(deviceId);if(status.connection!=='Connected'){status.command='Uncertain';continue;}const supported=starting?device.commands.find(c=>['Start','Enable'].includes(c)):device.commands.find(c=>['Stop','Disable'].includes(c));if(!supported)continue;status.command='Requested';setTimeout(()=>{status.command=status.connection==='Connected'?'Acknowledged':'Uncertain';log(run,`${device.name}: ${status.command.toLowerCase()}.`,{deviceId});if(active()?.id===run.id)App.render();},400);setTimeout(()=>{status.command=status.connection==='Connected'?'Completed':'Uncertain';status.operation=status.connection==='Connected'?(starting?'Active':'Stopped'):'Unavailable';log(run,`${device.name}: ${status.command.toLowerCase()}.`,{deviceId});if(active()?.id===run.id)App.render();},1000);}log(run,starting?'Group start requested.':'Group stop requested.');}
 else if(action==='command'){
 const s=run.deviceStates[id],device=Cousins.getDevice(id);if(!s||s.connection!=='Connected'){App.toast('Device is unavailable. Reconnect before sending commands.');return true;}const command=el.dataset.command;if(!device.commands.includes(command))return true;s.command='Requested';log(run,`${device.name}: ${command} requested.`);setTimeout(()=>{s.command=s.connection==='Connected'?'Acknowledged':'Uncertain';log(run,`${device.name}: ${s.command.toLowerCase()}.`,{deviceId:id});if(active()?.id===run.id)App.render();},500);setTimeout(()=>{if(s.connection!=='Connected'){s.command='Uncertain';log(run,`${device.name}: command uncertain.`,{deviceId:id,severity:'warning'});if(active()?.id===run.id)App.render();return;}s.command='Completed';s.operation=['Stop','Disable'].includes(command)?'Stopped':'Active';log(run,`${device.name}: ${command} completed.`);if(active()?.id===run.id)App.render();},1100);
 }
 else if(action==='apply-parameter'){const s=run.deviceStates[id],d=Cousins.getDevice(id);if(!s||s.connection!=='Connected'){App.toast('Device is unavailable.');return true;}const value=s.draft??s.applied;if(!Number.isFinite(value)||value<d.min||value>d.max){App.toast(`Enter ${d.min}–${d.max} ${d.unit}.`);return true;}s.command='Requested';log(run,`${d.parameter}: ${value} ${d.unit} requested.`,{deviceId:id});setTimeout(()=>{if(s.connection==='Connected'){s.applied=value;s.draft=null;}s.command=s.connection==='Connected'?'Completed':'Uncertain';log(run,`${d.parameter}: ${value} ${d.unit}.`);if(active()?.id===run.id)App.render();},700);}

 else return false;Cousins.save();App.render();return true;
 }
 function tick(){ticks++;for(const run of Cousins.db.collections){if(['Acquiring','Partial failure'].includes(run.acquisition))run.seconds++;const r=bounds(run);if(run.acquisition==='Completed'&&r.playbackState==='playing'){r.cursorSeconds=Math.min(r.endSeconds,r.cursorSeconds+r.speed);run.cursor=r.cursorSeconds;if(r.cursorSeconds>=r.endSeconds){r.playbackState='paused';run.viewing='Completed';}}if(App.ui.route==='active/'+run.id)paint(run);}if(ticks%10===0)Cousins.save();}
 function mount(){const run=active();if(run){bounds(run);paint(run);}}
 function unmount(){}
 setInterval(()=>{if(window.App)tick();},1000);
 return {render,start,action,mount,unmount,active,log,ensure,bounds,position,status,seek,speed};
})();
